// ═══════════════════════════════════════════════════════════════════════════
// MATISSE LISTENS — the cut-out the piece asks for, from what it is:
//   a quick, dense piece   the long wall of The Parakeet and the Mermaid: a frieze of big leaves read along the wall in
//                          rows, a leaf for every passage (high ones high in their row, loud ones large, a singing one
//                          a seaweed), the pomegranates in little clusters where the accents fall, and the parakeet
//                          where the piece sounds highest and loudest
//   an even, steady piece  the patchwork of painted sheets with a shape on each (The Creole Dancer): one sheet per
//                          passage, the rows as tall as the passages are long
//   a slow, singing piece  a band of tall strips across the wall with shapes dancing over them (The Velvets)
// the shapes: an accent a burst, a leap a coral, a held note a seaweed, a high line a dove, a low one a fish, the rest
// the hand-leaf; every one its chord's paper, and never on a paper of its own colour
// ═══════════════════════════════════════════════════════════════════════════
function matisseListen(ctx,CW,CH,chords,lim,gc,sessionSeed,mode){
  const ss=sessionSeed|0, isBW=mode==='bw', cn=chords.length, D=Math.min(CW,CH), reveal=_matReveal(chords,lim);
  const A=_kd2Analyze(chords,gc,mode), X=_hear(chords,A), st=_mtStats(chords,gc,isBW,0,cn); const dens=A.ch?A.ch.density:0.3;
  const ground = (X.pace>0.6 && dens>0.25) ? 'wall' : (X.regular>0.55 && X.pace>0.4) ? 'patch' : 'velvets';
  const wall=isBW?[242,240,234]:[246,242,233]; const O=_mtOps(); const placed=[];
  const colOn=(c,under)=>{ if(!under) return c; if(_mtSame(c,under)) return _mtFar(st.concat([_MT_WHITE,_MT_BLACK].map(_mtPastel)),under); const dh=Math.abs(((_mtHue(c)-_mtHue(under))%360+540)%360-180), dl=Math.abs(_mtLum(c)-_mtLum(under)); return (dh<70 && dl<0.25) ? _mtFar(st.concat([_MT_WHITE]),under) : c; };   // never lost on the paper under it
  const free=(x,y,s,tries,r,box)=>{ let bx=x,by=y,bd=-1; for(let k=0;k<tries;k++){ const cx=k?box[0]+r()*box[2]:x, cy=k?box[1]+r()*box[3]:y; let md=1e9; for(const p of placed) md=Math.min(md,Math.hypot(cx-p[0],cy-p[1])/(p[2]+s)); if(md>1.05) return [cx,cy]; if(md>bd){ bd=md; bx=cx; by=cy; } } return [bx,by]; };
  const isAcc=_mtAccOf(A);
  const shapeAt=(e,i,x,y,s,under,tt,acc,menu)=>{ const r=_mtR(57100+i,ss); const h=_mtHearSpan(A,Math.max(0,e.i-2),Math.min(cn,e.i+3)); let kind=acc?(menu==='wall'?'disc':'star'):_mtKindOf(h,r,null); if(kind==='feuille' && e.dur<0.5 && X.regular>0.5 && r()<0.3) kind='disc'; if(menu==='wall' && kind!=='disc' && kind!=='algae') kind='feuille';
    const sc=kind==='star'?0.55:kind==='disc'?0.3:kind==='bird'?0.8:kind==='fish'?0.75:1; const p=_mtPose(kind,h,r); const col=colOn(_mtPigAt(chords,e.i,gc,isBW),under);
    O.at(tt!=null?tt:e.i/cn, ()=>_mtPaper(ctx,_mtShapePolys(kind,x,y,s*sc,p.rot,57200+i*13+ss,p.fx),col,D,s>D*0.06?_mtR(57300+i,ss):null)); };
  if(ground==='wall'){ // the Parakeet and the Mermaid: a frieze of big leaves along the wall, the fruit in clusters, one parakeet
    O.at(0,()=>_mtWall(ctx,0,0,CW,CH,wall,ss)); const land=CW>CH*1.1, nR=land?2:3, bh=CH/nR;
    const G=_kd2Phrases(A,Math.round((land?8:9)+dens*5)); const n=G.length, per=Math.ceil(n/nR); const H=G.map(q=>_mtHearSpan(A,q.a,q.b));
    let pk=0, pv=-1; H.forEach((h,i)=>{ const v=h.reg*0.6+Math.min(1,h.vmax||0)*0.4; if(v>pv){ pv=v; pk=i; } });
    const accN=G.map(q=>{ let c=0; for(let e=q.a;e<q.b;e++) if(A.ev[e]&&isAcc(A.ev[e])) c++; return c; }); const fruitAt=new Set(accN.map((c,i)=>[c,i]).filter(x=>x[0]>0).sort((x,y)=>y[0]-x[0]||x[1]-y[1]).slice(0,Math.max(1,Math.round(n*0.45))).map(x=>x[1]));
    const warm=st.filter(p=>{ const hh=_mtHue(p); return (hh<40||hh>330) && _mtLum(p)<0.75 && !_mtSame(p,_MT_BLACK); }); let prev=null, prevK=null;
    G.forEach((q,i)=>{ const h=H[i], r=_mtR(57000+i,ss); const row=Math.min(nR-1,Math.floor(i/per)), k=i-row*per, cnt=Math.max(1,Math.min(per,n-row*per)); const fr=(k+0.5)/cnt, xr=(row%2)?1-fr:fr;
      const kind= i===pk ? 'bird' : h.dur>1.3 ? 'algae' : (prevK==='feuille' && r()<0.35) ? 'algae' : 'feuille'; prevK=kind;
      const s=Math.min(bh*0.36,CW*0.64/cnt)*(kind==='bird'?1.25:1)*(0.82+0.3*Math.min(1,h.vmax||0.6));
      let x=CW*(0.1+0.8*xr)+(r()-.5)*CW*0.04, y=bh*(row+0.5)+(0.5-h.reg)*bh*0.36; const xm=s*(kind==='bird'?1.08:0.92); x=Math.max(xm,Math.min(CW-xm,x)); y=Math.max(s*1.0,Math.min(CH-s*0.95,y)); placed.push([x,y,s*0.75]);
      let col=_mtPigAt(chords,Math.floor((q.a+q.b)/2),gc,isBW); if(_mtSame(col,prev)||_mtSame(col,_MT_WHITE)) col=_mtOther(st,[prev||[0,0,0],_MT_WHITE],isBW); if(kind==='bird' && !isBW) col=_mtOther([_mtPastel(_MT_PIG[6]),_mtPastel(_MT_PIG[5])].concat(st),[prev||[0,0,0],_MT_WHITE],isBW); prev=col;
      const p=_mtPose(kind,h,r); const rot=kind==='bird'?p.rot:p.rot*0.6+h.dir*0.08;
      O.at(q.t0,()=>_mtPaper(ctx,_mtShapePolys(kind,x,y,s,rot,57200+i*13+ss,p.fx),col,D,s>D*0.06?_mtR(57300+i,ss):null));
      // the pomegranates: a little cluster where an accent falls, three or four fruit together
      let made=0, last=-1e9; for(let e=q.a;e<q.b && made<(fruitAt.has(i)?1:0);e++){ const ev=A.ev[e]; if(!ev||!isAcc(ev)||e-last<(q.b-q.a)/3) continue; last=e; made++;
        const rr=_mtR(57400+i*5+made,ss), fs=D*(0.022+0.008*rr()); let [fx,fy]=free(x+(rr()-.5)*s*2.2,y+(rr()-.5)*s*1.6,fs*2.4,10,rr,[CW*0.05,bh*row+bh*0.08,CW*0.9,bh*0.84]); fx=Math.max(fs*3,Math.min(CW-fs*3,fx)); fy=Math.max(fs*3,Math.min(CH-fs*3,fy)); placed.push([fx,fy,fs*2.4]);
        const wc=warm.filter(p=>!_mtSame(p,col)); const fc=isBW?[60,60,64]:(wc.length?wc[i%wc.length]:_mtOther(st,[col,_MT_WHITE],isBW)); const nf=3+(rr()<0.5?1:0), a0=rr()*6.28;
        for(let f=0;f<nf;f++){ const ang=a0+f*6.2832/nf, d=f===3?0:fs*1.15; const cx=fx+Math.cos(ang)*d*(f===3?0:1), cy=fy+Math.sin(ang)*d*(f===3?0:1); O.at(e/cn,()=>_mtPaper(ctx,_mtShapePolys('disc',cx,cy,fs,0,57500+i*7+f+ss,1),fc,D,null)); } } }); }
  else if(ground==='patch'){ // the Creole Dancer: rows of sheets, each a passage with its shape
    const G=_kd2Phrases(A,CW>CH*1.1?10:12); const nR=Math.max(2,Math.min(4,Math.round(Math.sqrt(G.length*CH/CW)))); const per=Math.ceil(G.length/nR); const tot=G.reduce((s,q)=>s+q.n,0)||1;
    const m=D*0.035; O.at(0,()=>_mtWall(ctx,0,0,CW,CH,wall,ss)); let y=m; const rowsG=[]; for(let rI=0;rI<nR;rI++) rowsG.push(G.slice(rI*per,(rI+1)*per)); const rowsN=rowsG.filter(g=>g.length);
    let prev=null; rowsN.forEach((g,rI)=>{ const rn=g.reduce((s,q)=>s+q.n,0); const rh=(CH-2*m)*(0.6*rn/tot+0.4/rowsN.length); let x=m;
      g.forEach((q,j)=>{ const w=(CW-2*m)*q.n/rn; const r=_mtR(57500+rI*20+j,ss); let col=_mtPigAt(chords,Math.floor((q.a+q.b)/2),gc,isBW); if(_mtSame(col,prev)) col=_mtOther(st,[prev],isBW); prev=col;
        const sx=x, sy=y; O.at(q.t0,()=>_mtPaper(ctx,[_mtSheet(sx-D*0.002,sy-D*0.002,w+D*0.004,rh+D*0.004,r,D*0.01)],col,D,_mtR(57600+rI*20+j,ss),{strokes:4,shadow:0.004}));
        const h=_mtHearSpan(A,q.a,q.b); const e=A.ev[Math.floor((q.a+q.b)/2)]||A.ev[q.a]||{i:q.a,top:60,v:0.6,dur:1,acc:false}; const s=Math.min(w,rh)*0.44*(0.85+0.3*h.vmax);
        shapeAt(e,rI*20+j,sx+w*(0.5+(r()-.5)*0.15),sy+rh*(0.5+(r()-.5)*0.12),s,col,q.t0+(q.t1-q.t0)*0.4,h.acc>1&&r()<0.4,'patch'); x+=w; }); y+=rh; }); }
  else { // the Velvets: a band of tall strips, the shapes dancing over it
    O.at(0,()=>_mtWall(ctx,0,0,CW,CH,wall,ss)); const G=_kd2Phrases(A,CW>CH*1.1?9:7); const tot=G.reduce((s,q)=>s+q.n,0)||1; const bx0=CW*0.08, bw=CW*0.84, y0=CH*0.2, y1=CH*0.8; let x=bx0, prev=null; const strips=[];
    G.forEach((q,j)=>{ const w=bw*q.n/tot; const r=_mtR(57700+j,ss); let col=_mtPigAt(chords,Math.floor((q.a+q.b)/2),gc,isBW); if(_mtSame(col,prev)||_mtSame(col,_MT_WHITE)) col=_mtOther(st,[prev||[0,0,0],_MT_WHITE],isBW); prev=col;
      const sy=y0+(r()-.5)*CH*0.06, sh=(y1-y0)+(r()-.5)*CH*0.08, sx=x; strips.push({sx,w,col,sy,sh,t0:q.t0}); O.at(q.t0,()=>_mtPaper(ctx,[_mtSheet(sx-D*0.002,sy,w+D*0.004,sh,r,D*0.01)],col,D,_mtR(57800+j,ss),{strokes:4})); x+=w; });
    const E=_kd2Events(A,Math.round((7+dens*8)*_dW(dens))); const s0=D*0.16;
    E.forEach((e,i)=>{ const r=_mtR(57900+i,ss); let x=bx0+bw*(0.06+0.88*e.i/cn)+(r()-.5)*bw*0.05, y=(y0+y1)/2+(0.5-A.reg(e.top))*(y1-y0)*1.0; const s=s0*(0.75+0.45*e.v); [x,y]=free(x,y,s,6,r,[bx0,y0-CH*0.06,bw,y1-y0+CH*0.12]); x=Math.max(s*0.95,Math.min(CW-s*0.95,x)); y=Math.max(s*1.0,Math.min(CH-s*0.95,y)); placed.push([x,y,s]);
      const under=(strips.find(S=>x>=S.sx-s*0.3&&x<S.sx+S.w+s*0.3&&y>S.sy-s*0.6&&y<S.sy+S.sh+s*0.6)||{}).col; const tt=Math.max(e.i/cn,...strips.filter(S=>x+s>S.sx&&x-s<S.sx+S.w&&y+s>S.sy&&y-s<S.sy+S.sh).map(S=>S.t0+1e-6));   // over the strips, never under them
      shapeAt(e,i,x,y,s,under||wall,tt,isAcc(e),'velvets'); }); }
  O.run(reveal);
  try{ globalThis.__MT_LISTEN={v:'listen',ground,pace:X.pace,regular:X.regular,dens}; }catch(_){}
  _setCurE(0.5);
}

// ── Matisse's cut-out engine (gouaches découpées). One vocabulary of paper
// shapes — the algue frond, the leaf, the heart-leaf, the star, the pomegranate
// disc, the coral — every edge cut with scissors (a slight tremor along the
// outline, never a smooth bezier), every colour flat. Each phase lists its
// shapes first and draws them in time order, so the collage grows with the
// music and the same song + variant always recalls the identical picture.
function _matCut(ctx, pts, jit, rnd){
  // a polygon with scissor-cut edges: every vertex trembles a little
  ctx.beginPath();
  for(let i=0;i<pts.length;i++){ const [x,y]=pts[i]; const jx=(rnd()-.5)*jit, jy=(rnd()-.5)*jit; i?ctx.lineTo(x+jx,y+jy):ctx.moveTo(x+jx,y+jy); }
  ctx.closePath(); ctx.fill();
}
function _matBez(p0,p1,p2,p3,n,out){ for(let i=1;i<=n;i++){ const u=i/n, v=1-u; out.push([v*v*v*p0[0]+3*v*v*u*p1[0]+3*v*u*u*p2[0]+u*u*u*p3[0], v*v*v*p0[1]+3*v*v*u*p1[1]+3*v*u*u*p2[1]+u*u*u*p3[1]]); } }
// shapes are built in a local frame (centre 0,0; size ~1) and placed by _matPlace
function _matShapeLeaf(rnd){ const w=0.28+rnd()*0.16, pts=[[0,-1]]; _matBez([0,-1],[w*1.2,-0.55],[w*1.3,0.4],[0,1],10,pts); _matBez([0,1],[-w*1.3,0.4],[-w*1.2,-0.55],[0,-1],10,pts); return [pts]; }
function _matShapeHeart(rnd){ const w=0.55+rnd()*0.15, pts=[[0,0.95]]; _matBez([0,0.95],[w*1.4,0.1],[w*1.2,-0.95],[0,-0.45],10,pts); _matBez([0,-0.45],[-w*1.2,-0.95],[-w*1.4,0.1],[0,0.95],10,pts); return [pts]; }
function _matShapeAlgue(rnd){ // fronds fanning from one stem
  const n=3+(rnd()*3|0), tilt=(rnd()-.5)*0.5, spread=1.0+rnd()*0.8, by=0.85, polys=[];
  for(let j=0;j<n;j++){ const a=-1.5708+tilt+((n===1?0:(j/(n-1)-0.5))*spread), L=1.1+rnd()*0.6, w=0.17+rnd()*0.11;
    const dx=Math.cos(a), dy=Math.sin(a), px=-dy, py=dx; const P=(u,v)=>[dx*L*u+px*w*v, by+dy*L*u+py*w*v];
    const pts=[[0,by]]; _matBez([0,by],P(0.35,1.4),P(1.08,1.0),P(1,0),8,pts); _matBez(P(1,0),P(1.08,-1.0),P(0.35,-1.4),[0,by],8,pts); polys.push(pts); }
  return polys; }
function _matShapeStar(rnd){ const k=4+(rnd()*4|0), pts=[]; const inner=0.32+rnd()*0.2; for(let i=0;i<k*2;i++){ const a=i/(k*2)*6.2832-1.5708, q=(i%2)?inner:1; pts.push([Math.cos(a)*q,Math.sin(a)*q]); } return [pts]; }
function _matShapeDisc(rnd){ const pts=[]; const k=22; for(let i=0;i<k;i++){ const a=i/k*6.2832; const q=0.92+rnd()*0.1; pts.push([Math.cos(a)*q,Math.sin(a)*q]); } return [pts]; }
function _matShapeCoral(rnd){ // a branching coral / seaweed: a trunk with 2–3 forked lobes
  const polys=[], forks=2+(rnd()*2|0); for(let j=0;j<forks;j++){ const a=-1.5708+(j/(forks-1||1)-0.5)*1.4+(rnd()-.5)*0.3, L=0.9+rnd()*0.5, w=0.14+rnd()*0.08; const dx=Math.cos(a), dy=Math.sin(a), px=-dy, py=dx;
    const P=(u,v)=>[dx*L*u+px*w*v, 0.9+dy*L*u+py*w*v]; const pts=[[0,0.9]]; _matBez([0,0.9],P(0.3,1.2),P(0.7,1.5),P(1,0),7,pts); _matBez(P(1,0),P(0.7,-1.5),P(0.3,-1.2),[0,0.9],7,pts); polys.push(pts); }
  return polys; }
function _matShapeGerbe(rnd){ // La Gerbe frond: three or four long narrow lobes from one foot, barely fanning
  const n=3+(rnd()*2|0), spread=0.5+rnd()*0.3, by=0.95, polys=[];
  for(let j=0;j<n;j++){ const a=-1.5708+((j/(n-1))-0.5)*spread, L=1.5+rnd()*0.5, w=0.1+rnd()*0.06;
    const dx=Math.cos(a), dy=Math.sin(a), px=-dy, py=dx; const P=(u,v)=>[dx*L*u+px*w*v, by+dy*L*u+py*w*v];
    const pts=[[0,by]]; _matBez([0,by],P(0.3,1.3),P(1.06,1.0),P(1,0),8,pts); _matBez(P(1,0),P(1.06,-1.0),P(0.3,-1.3),[0,by],8,pts); polys.push(pts); }
  return polys; }
const _MAT_SHAPES={leaf:_matShapeLeaf, heart:_matShapeHeart, algue:_matShapeAlgue, gerbe:_matShapeGerbe, star:_matShapeStar, disc:_matShapeDisc, coral:_matShapeCoral};
function _matPlace(ctx, kind, cx, cy, size, rot, rgb, ss, idx){
  const rnd=_seedRnd(idx*13+2600, ss, 0, 0); rnd();
  const polys=_MAT_SHAPES[kind](rnd); const ca=Math.cos(rot), sa=Math.sin(rot);
  ctx.fillStyle=`rgb(${rgb[0]|0},${rgb[1]|0},${rgb[2]|0})`;
  for(const pts of polys){ _matCut(ctx, pts.map(([x,y])=>[cx+(x*ca-y*sa)*size, cy+(x*sa+y*ca)*size]), size*0.03, rnd); }
}
// flat paper colour from a chord: full saturation, one hue, the "Jazz" palette
function _matFlat(chords, idx, gc, isBW){
  const {rgb}=_picChord(chords, idx, gc, isBW); let [r,g,b]=rgb;
  if(isBW) return rgb;
  if(_pastelOn) return [Math.round(r),Math.round(g),Math.round(b)];
  const mx=Math.max(r,g,b,1), k=255/mx; let R=r*k,G=g*k,B=b*k; const m2=Math.max(R,G,B);
  const pull=(ch)=>ch===m2?ch:ch*0.45; return [Math.round(pull(R)),Math.round(pull(G)),Math.round(pull(B))];
}
function _matDraw(ctx, list, reveal, ss){
  list.sort((a,b)=>a.t-b.t || a.id-b.id);
  const n=Math.max(1, Math.ceil(list.length*Math.max(0,Math.min(1,reveal))));
  for(let i=0;i<n;i++){ const s=list[i]; _matPlace(ctx, s.kind, s.x, s.y, s.size, s.rot, s.col, ss, s.id); }
}
function _matReveal(chords, lim){ const cn=chords.length; return Math.max(0, Math.min(1, Math.max(1,Math.min(cn,lim))/cn)); }

const _matCss=(c,a)=>`rgba(${c[0]|0},${c[1]|0},${c[2]|0},${a==null?1:a})`; const _matMix=(a,b,t)=>[a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t];
// the figures of his cut-outs, in the same local frame (centre 0,0; size ~1): the seated blue nude, Icarus with his arms out,
// a dancer of the ring, a goldfish; and the palm frond
// a closed outline smoothed through its corners (Catmull-Rom), so a figure's edge curves as the scissors did
function _matSmooth(pts,k){ const n=pts.length, out=[]; for(let i=0;i<n;i++){ const p0=pts[(i-1+n)%n], p1=pts[i], p2=pts[(i+1)%n], p3=pts[(i+2)%n]; for(let j=0;j<k;j++){ const t=j/k, t2=t*t, t3=t2*t; out.push([0.5*((2*p1[0])+(-p0[0]+p2[0])*t+(2*p0[0]-5*p1[0]+4*p2[0]-p3[0])*t2+(-p0[0]+3*p1[0]-3*p2[0]+p3[0])*t3), 0.5*((2*p1[1])+(-p0[1]+p2[1])*t+(2*p0[1]-5*p1[1]+4*p2[1]-p3[1])*t2+(-p0[1]+3*p1[1]-3*p2[1]+p3[1])*t3)]); } } return out; }
function _matShapeSquare(rnd){ return [[[-0.9,-0.9],[0.9,-0.9],[0.9,0.9],[-0.9,0.9]]]; }
function _matShapeNude(rnd){ const pts=[[0.05,-1],[0.3,-0.9],[0.35,-0.6],[0.2,-0.45],[0.55,-0.3],[0.7,0.1],[0.5,0.3],[0.65,0.75],[0.4,0.95],[0.1,0.7],[-0.15,0.95],[-0.45,0.85],[-0.3,0.45],[-0.6,0.3],[-0.7,-0.1],[-0.4,-0.25],[-0.5,-0.6],[-0.25,-0.85],[-0.15,-1]]; return [_matSmooth(pts.map(([x,y])=>[x+(rnd()-.5)*0.04,y+(rnd()-.5)*0.04]),4)]; }
function _matShapeIcarus(rnd){ const pts=[[0,-1],[0.14,-0.92],[0.16,-0.7],[0.5,-0.55],[0.9,-0.75],[0.95,-0.6],[0.55,-0.3],[0.25,-0.25],[0.3,0.2],[0.45,0.95],[0.25,1],[0.08,0.3],[-0.1,0.95],[-0.3,1],[-0.25,0.2],[-0.3,-0.25],[-0.6,-0.4],[-0.95,-0.8],[-0.85,-0.9],[-0.45,-0.6],[-0.16,-0.7],[-0.14,-0.92]]; return [_matSmooth(pts.map(([x,y])=>[x+(rnd()-.5)*0.03,y+(rnd()-.5)*0.03]),3)]; }
function _matShapeDancer(rnd){ const lean=(rnd()-.5)*0.6; const pts=[[0.1,-1],[0.28,-0.85],[0.22,-0.6],[0.7,-0.45],[1,-0.2],[0.9,-0.05],[0.45,-0.2],[0.3,0.05],[0.55,0.6],[0.75,1],[0.5,1],[0.2,0.5],[-0.1,1],[-0.35,1],[-0.2,0.45],[-0.3,-0.05],[-0.75,0.15],[-1,0.45],[-0.95,0.25],[-0.6,-0.2],[-0.25,-0.5],[-0.15,-0.85]]; return [_matSmooth(pts.map(([x,y])=>[x+lean*(y+1)*0.3+(rnd()-.5)*0.03,y+(rnd()-.5)*0.03]),3)]; }
