  pass(v=>D*(0.022+0.018*v),0.08,glowCol); pass(v=>D*(0.009+0.007*v),0.24,glowCol); pass(v=>D*(0.0028+0.0035*v),0.95,()=>isBW?[250,250,248]:[255,248,232]);
