// Shared helper for the new Picasso phases: average a chord's colour + energy.
function _picChord(chords,idx,gc,isBW){
  const grey=(r,g,b)=>{const v=Math.round(r*0.299+g*0.587+b*0.114);return[v,v,v];};
  const chord=chords[Math.min(chords.length-1,Math.max(0,idx))];
  // Set the current chord's energy BEFORE calling gc so Real tone applies the
  // local dynamic level to every voice we sample here. _picChord is called by
  // ~all per-chord overlay sites (~99 callsites), so a single line here drives
  // pastel-at-piano / deep-at-forte modulation across the whole artist family.
  _setCurE(chord && chord._E);
  const notes=chord&&(chord.n||chord.notes||[]);
  let aR=0,aG=0,aB=0,aV=0,c=0;
  if(notes&&notes.length)for(const note of notes){const m=note.m!==undefined?note.m:note;const v=note.v!==undefined?note.v:80;const[r,g,b]=gc(m,v);aR+=r;aG+=g;aB+=b;aV+=v;c++;}
  if(!c)return{rgb:[120,100,160],energy:0.5};
  let rgb=[aR/c,aG/c,aB/c]; if(isBW)rgb=grey(rgb[0],rgb[1],rgb[2]);
  return{rgb:rgb.map(Math.round),energy:Math.max(0,Math.min(1,(aV/c-30)/90))};
}

// ── Picasso cubist facet engine ──────────────────────────────────────────────
// One primitive: the FACET — a plane cut out of the picture by straight lines,
// filled flat, shaded by a pencil hatch in one direction, and closed by a
// charcoal contour that is now and then left open so one plane passes into the
// next (the cubist "passage"). The composition is a recursive subdivision of a
// region into facets; facets are listed, sorted by musical time and drawn up to
// the reveal, so the picture fragments as the music goes and repaints
// identically for the same song and seed.
const _pcR=(a,ss)=>_seedRnd(a,ss,0,0);
const _pcClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const _pcMix=(a,b,t)=>[a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t];
const _pcCss=(c,a)=>`rgba(${c[0]|0},${c[1]|0},${c[2]|0},${a==null?1:a})`;
function _pcArea(p){ let a=0; for(let i=0;i<p.length;i++){ const q=p[(i+1)%p.length]; a+=p[i][0]*q[1]-q[0]*p[i][1]; } return Math.abs(a)/2; }
function _pcCentre(p){ let x=0,y=0; for(const q of p){ x+=q[0]; y+=q[1]; } return [x/p.length,y/p.length]; }
// split a convex polygon by the line through (px,py) at angle ang → [left,right]
function _pcSplit(poly,px,py,ang){
  const nx=-Math.sin(ang), ny=Math.cos(ang); const L=[],R=[]; const n=poly.length;
  for(let i=0;i<n;i++){ const a=poly[i], b=poly[(i+1)%n]; const da=(a[0]-px)*nx+(a[1]-py)*ny, db=(b[0]-px)*nx+(b[1]-py)*ny;
    (da>=0?L:R).push(a);
    if((da>=0)!==(db>=0)){ const t=da/(da-db); const ix=[a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t]; L.push(ix); R.push(ix); } }
  return [L,R];
}
// recursive subdivision: cut until the facet is small enough; grain biases the cut direction
function _pcCut(poly,rnd,minA,depth,grain,out){
  const A=_pcArea(poly); if(poly.length<3) return;
  if(A<minA*(0.6+rnd()*0.8) || depth>9){ out.push(poly); return; }
  const c=_pcCentre(poly); const px=c[0]+(rnd()-.5)*Math.sqrt(A)*0.5, py=c[1]+(rnd()-.5)*Math.sqrt(A)*0.5;
  const ang=(rnd()<0.6 ? grain+(rnd()-.5)*0.6 : rnd()*3.1416);
  const [L,R]=_pcSplit(poly,px,py,ang);
  if(L.length<3||R.length<3||_pcArea(L)<minA*0.15||_pcArea(R)<minA*0.15){ out.push(poly); return; }
  _pcCut(L,rnd,minA,depth+1,grain,out); _pcCut(R,rnd,minA,depth+1,grain,out);
}
function _pcPath(ctx,p){ ctx.beginPath(); for(let i=0;i<p.length;i++){ i?ctx.lineTo(p[i][0],p[i][1]):ctx.moveTo(p[i][0],p[i][1]); } ctx.closePath(); }
// draw one facet: {poly, col, hatch (0..1), hang, ink (contour alpha), open (edge index left open or -1), lw}
function _pcFacet(ctx,f,D,rnd){
  const p=f.poly;
  _pcPath(ctx,p); ctx.fillStyle=_pcCss(f.col,f.alpha==null?1:f.alpha); ctx.fill();
  if(f.hatch>0){ ctx.save(); _pcPath(ctx,p); ctx.clip(); const c=_pcCentre(p); const R=Math.sqrt(_pcArea(p))*1.2+D*0.02; const st=D*(0.009+(1-f.hatch)*0.012); const ca=Math.cos(f.hang), sa=Math.sin(f.hang);
    ctx.strokeStyle=_pcCss(f.inkCol||[20,18,16],0.14+f.hatch*0.22); ctx.lineWidth=Math.max(0.6,D*0.0022); ctx.lineCap='butt'; ctx.beginPath();
    for(let d=-R; d<=R; d+=st){ const jx=(rnd()-.5)*st*0.4; const x0=c[0]+ca*(d+jx)-sa*R, y0=c[1]+sa*(d+jx)+ca*R, x1=c[0]+ca*(d+jx)+sa*R, y1=c[1]+sa*(d+jx)-ca*R; ctx.moveTo(x0,y0); ctx.lineTo(x1,y1); }
    ctx.stroke(); ctx.restore(); }
  if(f.ink>0){ ctx.strokeStyle=_pcCss(f.inkCol||[22,20,18],f.ink); ctx.lineWidth=f.lw||Math.max(1,D*0.004); ctx.lineCap='round'; ctx.lineJoin='round';
    for(let i=0;i<p.length;i++){ if(i===f.open) continue; const a=p[i], b=p[(i+1)%p.length]; const g=rnd()<0.22; // a broken edge: two short strokes with a gap
      ctx.beginPath(); if(g){ const u=0.35+rnd()*0.3; ctx.moveTo(a[0],a[1]); ctx.lineTo(a[0]+(b[0]-a[0])*(u-0.12),a[1]+(b[1]-a[1])*(u-0.12)); ctx.moveTo(a[0]+(b[0]-a[0])*(u+0.12),a[1]+(b[1]-a[1])*(u+0.12)); ctx.lineTo(b[0],b[1]); } else { ctx.moveTo(a[0],a[1]); ctx.lineTo(b[0],b[1]); } ctx.stroke(); } }
}
function _pcSetup(chords,gc,mode){ const isBW=mode==='bw'; const ch=(typeof computeSongCharacter==='function')?computeSongCharacter(chords):null;
  return {cn:chords.length,isBW,energy:ch?ch.energy:0.5,density:ch?ch.density:0.5,register:ch?ch.register:0.5,tempo:ch?ch.tempo:0.5,
    col:(t)=>{ const cn=chords.length; const r=_picChord(chords,_pcClamp(Math.floor(t*cn),0,cn-1),gc,isBW); return r; }}; }
function _pcDraw(ctx,list,reveal,D,ss){ const oa=list._objA; list.sort((a,b)=>(a.t-b.t)||(a.id-b.id)); const n=Math.ceil(list.length*_pcClamp(reveal,0,1)); for(let i=0;i<(oa?list.length:n);i++){ const f=list[i]; if(i>=n && !f.fig) continue; const rnd=_pcR(f.id*17+91001,ss); rnd(); _pcFacet(ctx,f,D,rnd); } }

// ── Picasso 5 · Les Demoiselles (1907) — tall angular figures side by side,
// rose and ochre flesh cut by the blue of the curtain, white highlights and
// black contours; each figure is one passage of the song, left to right.
function picassoPhaseDemoiselles(ctx,CW,CH,chords,lim,gc,ss,mode){
  const S=_pcSetup(chords,gc,mode), D=Math.min(CW,CH), cn=S.cn; const reveal=Math.max(1,Math.min(cn,lim))/cn, isBW=S.isBW;
  ctx.fillStyle=isBW?'#cfcac2':'#dcc0a2'; ctx.fillRect(0,0,CW,CH);
  const r0=_pcR(94000,ss); r0();
  const ROSE=[232,160,128], OCHRE=[214,164,96], BLUE=[112,146,188], WHITE=[244,236,222], SHADOW=[132,84,70];
  const nf=Math.round((3+S.density*2)*_dW(S.density)); const list=[]; let id=0;
  // the figures: not tall boxes but bodies — a head (the mask), shoulders, a raised arm on every other one, the waist in,
  // the hips out, the legs apart; the middle one sits lower. Each is one passage of the song, left to right.
  const strips=[], heads=[]; for(let k=0;k<nf;k++){ const x0=(k+0.04+r0()*0.08)/nf, x1=(k+0.96-r0()*0.08)/nf; const w=(x1-x0), xm=(x0+x1)/2, lean=(r0()-.5)*0.06;
    const seated = nf>=3 && k===nf-1; const top=(seated?0.38:0.04+(k%2)*0.04)+r0()*0.06, bot=0.94+r0()*0.06;   // the last one squats, the others stand at two heights
    const H=bot-top, nk=top+H*0.14, sh=top+H*0.2, wa=top+H*0.5, hp=top+H*0.62, kn=top+H*0.82;   // neck, shoulders, waist, hips, knees
    const raised = !seated && (k%2===1 || nf<3);   // the raised arm, bent at the elbow, up behind the head
    const P=[];
    P.push([xm-w*0.14+lean,nk]);                                                           // neck, left
    P.push([x0+w*0.02-lean,sh]);                                                           // left shoulder
    if(raised && k%2===1){ P.push([x0-w*0.1-lean,sh+H*0.22]); P.push([x0+w*0.1-lean,sh+H*0.26]); }   // the left arm out and down, bent
    P.push([x0+w*0.12-lean*0.5,wa]);                                                       // the waist, in
    P.push([x0+w*0.0,hp]);                                                                 // the hip, out
    P.push([x0+w*0.1,kn]); P.push([x0+w*0.18,bot]);                                        // the left leg
    P.push([xm-w*0.04,bot]); P.push([xm,kn+H*0.04]); P.push([xm+w*0.04,bot]);              // the legs apart
    P.push([x1-w*0.18,bot]); P.push([x1-w*0.1,kn]);                                        // the right leg
    P.push([x1-w*0.0,hp]);                                                                 // the hip
    P.push([x1-w*0.12+lean*0.5,wa]);                                                       // the waist
    if(raised){ P.push([x1-w*0.02+lean,sh+H*0.1]); P.push([x1+w*0.12+lean,top+H*0.04]); P.push([x1+w*0.04+lean,top-0.03]); P.push([xm+w*0.22+lean,sh-H*0.02]); }   // the raised arm: elbow out, hand up behind the head
    else { P.push([x1-w*0.02+lean,sh]); }                                                  // the right shoulder
    P.push([xm+w*0.14+lean,nk]);                                                           // neck, right
    strips.push(P.map(([x,y])=>[CW*x,CH*y]));
    // the head: an angular mask, narrower than the shoulders, turned a little
    const hw=w*(seated?0.42:0.36), hh=H*(seated?0.27:0.17), hy=top+H*(seated?0.1:0.07), tilt=(r0()-.5)*0.4;
    heads.push({poly:_pgRot([[xm-hw*0.6,hy-hh*0.55],[xm+hw*0.5,hy-hh*0.6],[xm+hw*0.7,hy-hh*0.1],[xm+hw*0.45,hy+hh*0.6],[xm-hw*0.25,hy+hh*0.65],[xm-hw*0.72,hy+hh*0.15]].map(([x,y])=>[CW*x,CH*y]),CW*xm,CH*hy,tilt), xm, hy, hw, hh, k, tilt}); }
  const minA=CW*CH/(70+S.density*80);
  strips.forEach((strip,k)=>{ const rr=_pcR(94100+k,ss); rr(); const out=[]; _pcCut(strip,rr,minA*1.7,0,(k%2?1.15:2.0)+(rr()-.5)*0.5,out); const cx=_pcCentre(strip)[0];   // the facets lean: left on one, right on the next
    for(const poly of out){ const pc=_pcCentre(poly); const t=_pcClamp((k+(pc[1]/CH))/nf*0.96+rr()*0.03,0,1); const {rgb,energy}=S.col(t);
      const side=(pc[0]-cx)/(CW/nf); const u=rr(); let base = u<0.08 ? WHITE : u<0.2 ? SHADOW : (side<-0.15 ? ROSE : side>0.2 ? OCHRE : (rr()<0.5?ROSE:OCHRE));
      let col=isBW?rgb:_pcMix(base,rgb,0.28); if(base===WHITE) col=isBW?[240,236,230]:_pcMix(WHITE,rgb,0.12);
      col=_pcMix(col,[0,0,0],Math.max(0,energy-0.6)*0.5);
      list.push({fig:true,id:id++,t,poly,col,hatch:base===SHADOW?0.6:(rr()<0.25?0.3:0),hang:(rr()-.5)*0.8+(side>0?0.8:-0.8),ink:0.9,inkCol:[24,18,16],open:rr()<0.35?Math.floor(rr()*poly.length):-1,lw:Math.max(1.2,D*0.005)}); } });
  // the masks: a few big facets in ochre and rose, the eyes as dark almonds, the nose one wedge — the song's colour at the figure's start
  heads.forEach((h)=>{ const rr=_pcR(94300+h.k,ss); rr(); const out=[]; _pcCut(h.poly,rr,minA*0.5,0,0.4+(rr()-.5)*0.8,out); const t0=_pcClamp(h.k/nf*0.96,0,1); const {rgb}=S.col(t0);
    const afr = h.k>=nf-2 && nf>=3;   // the striped masks at the right
    for(const poly of out){ const u=rr(); const base=afr ? (u<0.35?OCHRE:u<0.6?[122,140,92]:u<0.85?ROSE:SHADOW) : (u<0.3?ROSE:u<0.75?OCHRE:u<0.88?WHITE:SHADOW); const col=isBW?_pcMix(rgb,[210,206,200],0.4):_pcMix(base,rgb,0.22);
      list.push({fig:true,id:id++,t:t0+0.01,poly,col,hatch:afr?0.55:(base===SHADOW?0.5:0),hang:afr?(0.3+(rr()-.5)*0.4):0.6,ink:0.95,inkCol:[24,18,16],open:-1,lw:Math.max(1.2,D*0.005)}); }
    const E=(dx,dy,sx)=>_pgRot(_pgEll(h.xm+dx*h.hw,h.hy+dy*h.hh,h.hw*0.17*sx,h.hh*0.05,0.25,8).map(([x,y])=>[CW*x,CH*y]),CW*h.xm,CH*h.hy,h.tilt);
    list.push({fig:true,id:id++,t:t0+0.02,poly:E(-0.3,-0.15,1),col:isBW?[20,20,20]:[28,22,20],hatch:0,hang:0,ink:0,open:-1});   // the eyes
    list.push({fig:true,id:id++,t:t0+0.02,poly:E(0.32,-0.2,1.3),col:isBW?[20,20,20]:[28,22,20],hatch:0,hang:0,ink:0,open:-1});
    list.push({fig:true,id:id++,t:t0+0.02,poly:_pgRot([[h.xm-h.hw*0.05,h.hy-h.hh*0.1],[h.xm+h.hw*0.22,h.hy+h.hh*0.3],[h.xm-h.hw*0.1,h.hy+h.hh*0.32]].map(([x,y])=>[CW*x,CH*y]),CW*h.xm,CH*h.hy,h.tilt),col:isBW?[150,146,140]:_pcMix(SHADOW,rgb,0.2),hatch:0.5,hang:1.2,ink:0.9,inkCol:[24,18,16],open:-1,lw:Math.max(1,D*0.004)}); });   // the nose, one wedge
  // the still life in front: a cloth and three fruit, on the loud pieces
  if(S.energy>0.35){ const fy=0.9; list.push({id:id++,t:0.98,poly:[[CW*0.3,CH*fy],[CW*0.7,CH*(fy-0.02)],[CW*0.74,CH],[CW*0.26,CH]],col:isBW?[230,228,224]:_pcMix(WHITE,S.col(0.98).rgb,0.1),hatch:0.2,hang:0.1,ink:0.7,inkCol:[40,36,40],open:-1,lw:Math.max(1,D*0.003)});
    [[0.42,0.93,[120,170,90]],[0.5,0.95,[200,60,50]],[0.58,0.93,[232,196,60]]].forEach(([fx,fyy,c],i)=>list.push({id:id++,t:0.99,poly:_pgEll(fx,fyy,0.04,0.03,0.2,9).map(([x,y])=>[CW*x,CH*y]),col:isBW?[160,160,160]:_pcMix(c,S.col(0.99).rgb,0.3),hatch:0,hang:0,ink:0.9,inkCol:[24,18,16],open:-1,lw:Math.max(1,D*0.004)})); }
  // the curtain behind: blue and white planes cut with a vertical grain, quiet, drawn first (t slightly ahead of the figure beside them)
  const bk=[]; const rb=_pcR(94900,ss); rb(); _pcCut([[0,0],[CW*0.55,0],[CW*0.45,CH],[0,CH]],rb,minA*2.6,0,0.9+(rb()-.5)*0.5,bk); _pcCut([[CW*0.55,0],[CW,0],[CW,CH],[CW*0.45,CH]],rb,minA*2.6,0,2.2+(rb()-.5)*0.5,bk);   // the curtain's folds fall from both top corners, big planes
  for(const poly of bk){ const pc=_pcCentre(poly); const t=_pcClamp(pc[0]/CW,0,1); const {rgb}=S.col(t); const u=rb(); const base=u<0.55?BLUE:u<0.8?WHITE:[196,170,140];
    list.push({id:id++,t:_pcClamp(Math.floor(pc[0]/CW*nf)/nf-0.06,0,1),poly,col:isBW?_pcMix(rgb,[200,200,200],0.5):_pcMix(base,rgb,0.18),hatch:base===BLUE?0.35:0,hang:1.4+(rb()-.5)*0.4,ink:0.45,inkCol:[40,36,40],open:rb()<0.4?Math.floor(rb()*poly.length):-1,lw:Math.max(1,D*0.003)}); }
  { const rd=_pcR(94950,ss); rd(); const dr=[]; _pcCut([[0,CH*0.3],[CW*0.16,CH*0.22],[CW*0.22,CH*0.6],[CW*0.14,CH],[0,CH]],rd,minA*1.4,0,1.3,dr); for(const poly of dr){ const u=rd(); list.push({id:id++,t:0.005,poly,col:isBW?[236,234,230]:_pcMix(u<0.7?WHITE:[214,196,176],S.col(0.02).rgb,0.08),hatch:u<0.4?0.3:0,hang:1.1,ink:0.6,inkCol:[70,62,60],open:-1,lw:Math.max(1,D*0.003)}); } }   // the white drape at the left, where the first one stands
  list._objA=!!chords._objFirst;   // a Compose take: every figure stands from the first note
  _pcDraw(ctx,list,reveal,D,ss);
  _setCurE(0.5);
}


// ═══════════════════════════════════════════════════════════════════════════
// PICASSO — six paintings, each built on the facet engine above (_pcCut /
// _pcFacet) from flat planes with charcoal contours, and read from the music:
// the head's facets are the phrases, the eyes the tonic and the dominant, the
// strings the voices, the figures the sections, the one line the melody.
// ═══════════════════════════════════════════════════════════════════════════
const _pgEll=(cx,cy,rx,ry,rot,n)=>{ const p=[]; const c=Math.cos(rot||0), s=Math.sin(rot||0); for(let i=0;i<(n||18);i++){ const a=i/(n||18)*6.2832; const x=Math.cos(a)*rx, y=Math.sin(a)*ry; p.push([cx+x*c-y*s, cy+x*s+y*c]); } return p; };
const _pgRot=(pts,cx,cy,rot)=>{ const c=Math.cos(rot), s=Math.sin(rot); return pts.map(([x,y])=>[cx+(x-cx)*c-(y-cy)*s, cy+(x-cx)*s+(y-cy)*c]); };
const _pgRect=(cx,cy,w,h,rot)=>_pgRot([[cx-w/2,cy-h/2],[cx+w/2,cy-h/2],[cx+w/2,cy+h/2],[cx-w/2,cy+h/2]],cx,cy,rot||0);
const _pgN=(pts,CW,CH)=>pts.map(([x,y])=>[x*CW,y*CH]);
// a flat plane: facet record without hatch, with a contour
const _pgF=(id,t,poly,col,o)=>Object.assign({id,t,poly,col,hatch:0,hang:0,ink:0.9,inkCol:[22,20,18],open:-1},o||{});
// Picasso's 1937 palette pushed onto a song colour
const _PC_PAL={ yellow:[232,196,60], green:[120,170,90], violet:[150,110,170], rose:[228,160,140], white:[244,238,226], red:[200,60,50], blue:[70,110,160], ochre:[196,150,80], black:[24,22,20] };
