  for(let k=0;k<nB;k++){ let best=null; for(const o of sal){ if(o.e.t<k/nB||o.e.t>=(k+1)/nB||inR.has(o.e)||o.e.dur>dMed) continue; if(!best||o.s>best.s) best=o; } if(best) bars.push(best.e); }
