  const ss=sessionSeed|0,isBW=mode==='bw',cn=chords.length,N=Math.max(1,Math.min(cn,lim));
  ctx.fillStyle=isBW?'#101010':'#180a18';ctx.fillRect(0,0,CW,CH);
  const _bd=(()=>{ try{ return computeSongCharacter(chords).density; }catch(_){ return 0.4; } })();
  const frames=cn<=8?Math.max(2,cn):cn<=30?7:cn<=80?11:Math.round(10+16*_bd);   // a long piece: as many frames as it is dense
  const vis=Math.max(1,Math.ceil(N/cn*frames));
