  if(w>7 && !flat){ ctx.fillStyle=`rgba(${(r*0.5)|0},${(g*0.5)|0},${(b*0.55)|0},${(a*0.3).toFixed(2)})`; rib(-sa*w*0.12+w*0.05, ca*w*0.12+w*0.07, 1.0, 0); }   // relief (only where the touch is big enough to cast one; the underpainting is flat)
