function drawThomasOverlay(ctx, CW, CH, chords, lim, gc, sessionSeed, mode, phaseIndex){
  if(!lim || !chords || !chords.length) return;
  // VARIANT: 0 What she heard (_thListen: her Sonata, one colour over the others; the first, a chooser of her paths, retired as _thListenOld, code kept) · 1 Resurrection · 2 Concerto · 3 Starry Night · 4 Snoopy · 5 Eclipse · 6 Red Azaleas. Free: 0 and 1.
  const _pn=_capN(7); const pick0=((phaseIndex|0)%_pn+_pn)%_pn;
  if(pick0===0){ _thListen(ctx,CW,CH,chords,lim,gc,sessionSeed,mode); return; }
  const pick=pick0-1;
  const isBW=mode==='bw', cn=chords.length, ss=sessionSeed|0;
  const L=_thLayout(CW, CH, chords, ss, pick), P=L.P;
  const _ch=(typeof computeSongCharacter==='function') ? computeSongCharacter(chords) : null;
  const energy=_ch ? _ch.energy : 0.5;
  // ── the reading of the piece: each chord's colour (lazily, through gc), its
  // velocity — half absolute, half within the piece, so a flat MIDI still breathes —
  // and its top note
  const col=new Array(cn), vel=new Float32Array(cn), top=new Int16Array(cn);
  let vMin=127, vMax=0;
  for(let i=0;i<cn;i++){ const ns=(chords[i]&&(chords[i].n||chords[i].notes))||[]; let v=0, t=0;
    for(const n of ns){ v+=(n&&n.v!==undefined)?n.v:80; const m=(n&&n.m!==undefined)?n.m:n; if(m>t) t=m; }
    vel[i]=ns.length ? v/ns.length : 80; top[i]=t; if(vel[i]<vMin) vMin=vel[i]; if(vel[i]>vMax) vMax=vel[i]; }
  const vr=vMax-vMin;
  for(let i=0;i<cn;i++) vel[i]=Math.max(0, Math.min(1, 0.5*vel[i]/127 + 0.5*(vr>6 ? (vel[i]-vMin)/vr : 0.6)));
  const chordCol=(i)=>{ if(col[i]) return col[i];
    const chord=chords[i]; _setCurE(chord && chord._E);
    const notes=chord && (chord.n || chord.notes);
    if(!notes || !notes.length) return (col[i]=[200,150,120]);
    let r=0,g=0,b=0,c=0,k=0;
    for(const note of notes){ const m=note.m!==undefined?note.m:note, v=note.v!==undefined?note.v:80; const q=gc(m,v); r+=q[0]; g+=q[1]; b+=q[2]; k+=Math.max(q[0],q[1],q[2])-Math.min(q[0],q[1],q[2]); c++; }
    r/=c; g/=c; b/=c; k/=c;
    // her colours are pure: the mean of a chord's notes keeps the chroma its notes have (averaging alone greys a chord)
    const l=(r+g+b)/3, k0=Math.max(r,g,b)-Math.min(r,g,b), f=k0>4 ? Math.min(2.2, k/k0) : 1;
    return (col[i]=[Math.max(0,Math.min(255,l+(r-l)*f)), Math.max(0,Math.min(255,l+(g-l)*f)), Math.max(0,Math.min(255,l+(b-l)*f))]); };
  const lift=(c,f)=>[Math.min(255,c[0]*f), Math.min(255,c[1]*f), Math.min(255,c[2]*f)];
  const mix=(a,b,t)=>[a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t];
  const css=(c)=>`rgb(${c[0]|0},${c[1]|0},${c[2]|0})`;
  // ── the ground: cream, or night blue for the Starry Night (a dark grey in Black & White)
  ctx.fillStyle=(pick===2 && isBW) ? 'rgb(38,38,40)' : (isBW ? 'rgb(242,241,238)' : css(P.ground));
  ctx.fillRect(0,0,CW,CH);
  // ── per-variant colour readings, from the whole piece
  let rootC=null, loudC=null; const loud=pick===5 ? new Uint8Array(cn) : null, star=pick===2 ? new Uint8Array(cn) : null;
  if(pick===2){ // the stars: the high notes of every passage — a chord whose top note stands above ~¾ of the chords
    // around it (±12) is painted pale, so the night is starred all over, thickest where the melody climbs
    for(let i=0;i<cn;i++){ let lo=0, n=0; for(let j=Math.max(0,i-12); j<=Math.min(cn-1,i+12); j++){ if(j===i) continue; n++; if(top[j]<top[i]) lo++; } star[i]=(n>0 && lo>=n*0.74) ? 1 : 0; } }
  if(pick===5){ // two tones: the root chord, and the loud (climax) chords in a second colour
    const pw=new Float32Array(12);
    for(let i=0;i<cn;i++){ const ns=(chords[i]&&chords[i].n)||[]; for(const n of ns){ const m=(n&&n.m!==undefined)?n.m:60; pw[((m%12)+12)%12]+=((chords[i].durQ||1)*(0.4+vel[i])); } }
    let tonic=0; for(let k=1;k<12;k++) if(pw[k]>pw[tonic]) tonic=k;
    let ri=0; for(let i=0;i<cn;i++){ const ns=(chords[i]&&chords[i].n)||[]; let lo=999; for(const n of ns){ const m=(n&&n.m!==undefined)?n.m:60; if(m<lo) lo=m; } if(lo<999 && ((lo%12)+12)%12===tonic){ ri=i; break; } }
    rootC=chordCol(ri);
    const sc=Array.from(vel).map((v,i)=>v+0.25*((chords[i]&&typeof chords[i]._E==='number')?chords[i]._E:0.5));
    const so=sc.slice().sort((a,b)=>a-b); let loudCut=so[Math.min(cn-1, Math.floor(cn*0.76))];
    if(loudCut<=so[0]+1e-6) loudCut=so[0]-1;   // a piece without dynamics: the second tone follows the energy alone
    // the second tone: of the loud chords, the one whose colour stands farthest from the root
    let bd=-1; for(let i=0;i<cn;i++){ if(sc[i]<loudCut) continue; const c=chordCol(i); const d=Math.abs(c[0]-rootC[0])+Math.abs(c[1]-rootC[1])+Math.abs(c[2]-rootC[2]); if(d>bd){ bd=d; loudC=c; } }
    if(!loudC || bd<70){ const l=rootC[0]*0.299+rootC[1]*0.587+rootC[2]*0.114; loudC=l>140 ? lift(rootC,0.55) : mix(rootC,[255,255,255],0.45); }
    for(let i=0;i<cn;i++) loud[i]=sc[i]>=loudCut ? 1 : 0;
  }
  // Snoopy: each column is ONE colour — the colour of the chord that opens it
  const _thNew=true;   // (17 Nov 2026) her paint, not light; her hand freer; the Starry Night a night; the Eclipse in rings of one colour each
  // the astronauts in the Starry Night: the loudest chords keep their own warm colour, every other dab is night
  const astro=new Uint8Array(cn); if(_thNew&&pick===2){ const so=Array.from(vel).sort((a,b)=>a-b), cut=so[Math.min(cn-1,Math.floor(cn*0.93))]; for(let i=0;i<cn;i++) astro[i]=vel[i]>=cut&&cut>so[0]?1:0; }
  const segC=(pick===3||(_thNew&&pick===4)) ? new Array(L.seg.length) : null;
  if(segC){ for(const d of L.D) if(!segC[d.g]) segC[d.g]=chordCol(d.c); }
  const jit=_thNew?0.2+0.1*energy:0.1+0.08*energy;     // the energy of the piece: how freely the hand cuts the corners
  for(const d of L.D){
    if(d.c>=lim) break;          // dabs run in chord order — the painting grows with the music
    const v=vel[d.c];
    let c;
    if(pick===3||(_thNew&&pick===4)) c=lift(segC[d.g], 0.74+0.42*v);
    else if(pick===5) c=loud[d.c] ? lift(loudC, 0.92+0.16*v) : lift(rootC, 0.8+0.34*v);
    else {
      c=lift(chordCol(d.c), 0.86+0.26*v);
      if(pick===2 && star[d.c]) c=isBW ? [236,236,236] : mix(c,[236,241,255],0.82);
      else if(_thNew && pick===2 && !astro[d.c] && !isBW) c=mix(c,[22,40,118],0.66);
    }
    if(_thNew && !isBW && !(pick===2 && star[d.c])) c=_bhxPigment(c,0.35,0.72,0.2,0.8,0.05,0.4,null);
    c=lift(c, 1+d.lt*0.08);      // no two dabs quite the same
    _setCurE(chords[d.c] && chords[d.c]._E);
    ctx.fillStyle=css(c);
    _thDab(ctx, d.x, d.y, d.len, d.pl*(0.62+0.2*v), d.ang, d.q, jit);
  }
  // the Eclipse: the dark sun in the eye of the rings
  if(pick===4){ const [cx,cy]=_thCtr(P, CW, CH), r=L.p*1.2; const c0=chordCol(0);
    ctx.fillStyle=isBW ? 'rgb(28,28,30)' : css(mix(lift(c0,0.25),[12,16,48],0.6));
    ctx.beginPath(); for(let k=0;k<16;k++){ const a=k/16*6.2832, q=r*(0.96+0.08*Math.sin(k*2.3+ss)); k?ctx.lineTo(cx+Math.cos(a)*q,cy+Math.sin(a)*q):ctx.moveTo(cx+Math.cos(a)*q,cy+Math.sin(a)*q); } ctx.closePath(); ctx.fill(); }
  _setCurE(0.5);
}

function drawKandinskyOverlay(ctx, CW, CH, chordCount, sessionSeed, mode, gc, phaseIndex, cn, chords){
  if(chordCount === 0) return;
  const ss = sessionSeed|0;
  // ── Progress-stretch (per phase) ──
  // Kandinsky's phases pick element counts from ABSOLUTE thresholds (countFor)
  // and grid breakpoints. A single fixed REF finished phases whose top threshold
  // was below REF *before* the song ended (e.g. Circles maxes at 230, so REF 300
  // saturated it at 77% of the track). Instead each phase gets an effCount scaled
  // to ITS OWN top threshold, so the final element lands exactly on the last note.
  const _cn = (cn && cn > 0) ? cn : chordCount;       // fallback if cn not passed
  const prog = Math.max(0, Math.min(1, chordCount / _cn));
  // Song character (A2): a loud/dense piece fills the composition with more
  // elements (livelier Bauhaus chatter); a calm/sparse one stays open and quiet.
  // Multiplier 0.72..1.28, applied to every phase's element budget via eff().
  const _ch = (chords && typeof computeSongCharacter==='function') ? computeSongCharacter(chords) : null;
  const _charDrive = _ch ? (0.55*_ch.energy + 0.45*_ch.density) : 0.5;
  const _elMul = 0.50 + 1.01*_charDrive;   // amplified ×1.8 (was 0.72+0.56)
  const eff = (ref) => Math.max(1, Math.round(prog * ref * _elMul));
  // Song-aware palette: sample gc() at the song's TOP 8 pitch classes so the
  // Kandinsky canvas inherits the piece's actual colour DNA. Harmony yields
  // a circle-of-fifths family rooted in the song's harmonic centre, Spectral
  // a chromatic spread of the song's loud pitches, B/W a grey scale, Custom
  // the user's palette mapped to those anchors. Two different pieces in the
  // same mode now render to different Kandinsky palettes. Static mid-register
  // fallback when chord data is unavailable.
  const palette = (()=>{
    if(typeof gc !== 'function') return null;
    const tops = (typeof _songTopPitches === 'function') ? _songTopPitches(chords, 8) : null;
    const pitches = (tops && tops.length) ? tops : [60,64,67,71,74,77,55,48];   // fallback: mid/low spread
    return pitches.map(m=>{ const c=gc(m,100); return Array.isArray(c)?`rgb(${c[0]},${c[1]},${c[2]})`:c; });
  })();
  // ── VARIANT: 0 Cosmic scatter (the free composition below) · 1 Composition VIII ·
  // 2 Several Circles · 3 Circles in a Circle · 4 Yellow–Red–Blue · 5 Improvisation ·
  // 6 On White II · 7 Composition X (the _kd2 painters). Free: 0 and 1. The Next
  // button cycles phaseIndex; _capN caps it on Free.
  // VARIANT: 0 What he heard (_kdListen, generative) · 1 Cosmic scatter · 2 Composition VIII · 3 Several Circles · 4 Circles in a Circle · 5 Yellow–Red–Blue · 6 Improvisation · 7 On White II (Composition X retired, approved). Free: 0 and 1.
  const _pn=_capN(8); const pick0=((phaseIndex|0)%_pn+_pn)%_pn;
  if(pick0===0){ _kdListen(ctx, CW, CH, chordCount, ss, mode, chords, gc); return; }
  const pick=pick0-1;
  if(pick>0){ _kd2Paint(pick, ctx, CW, CH, chordCount, ss, mode, chords, gc); return; }
  kandinskyPhaseA(ctx, CW, CH, eff(280), ss, mode, palette, chords);
}

// ── Kandinsky phase A: the original free "cosmic scatter" composition. ──
function kandinskyPhaseA(ctx, CW, CH, chordCount, sessionSeed, mode, palette, chords){
  const ss = sessionSeed|0;
  const isBW = mode==='bw';

  const TH_TRI    = [2, 6, 12, 20, 32, 48, 75, 120, 180, 260];
  const TH_RING   = [4, 11, 22, 38, 60, 95, 140, 200, 280];
  const TH_LINE   = [1, 4, 8, 13, 19, 27, 38, 52, 70, 100, 140, 190, 250];
  const TH_ARC    = [7, 18, 32, 50, 80, 125, 180, 250];
  const TH_ZIG    = [10, 24, 42, 70, 110, 160, 220];

  // chordCount here is the per-phase effCount (REF 280 for this phase). The old
  // countFor() used sparse thresholds whose top entries were far apart, so the
  // back half of a long song added almost nothing (looked frozen). Instead scale
  // each element type LINEARLY with progress: count = round(p · maxForType),
  // where maxForType = how many that type has at full build (= thresholds.length).
  const _prog = Math.max(0, Math.min(1, chordCount / 280));
  const countFor = (thresholds) => Math.round(_prog * thresholds.length);

  // Kandinsky palette -- tuned to the active scheme when a palette is supplied
  // (Harmony/Spectral/B-W/Custom); otherwise falls back to the classic fixed set.
  const lineColors = palette || [
    'rgba(225, 60, 50, 0.92)',     // saturated red
    'rgba(240, 180, 30, 0.92)',    // golden yellow
    'rgba(40, 70, 200, 0.92)',     // saturated blue
    'rgba(180, 60, 200, 0.90)',    // purple
    'rgba(245, 238, 220, 0.90)',   // cream white
    'rgba(8, 4, 12, 0.92)',        // near-black
    'rgba(50, 160, 80, 0.90)',     // forest green
    'rgba(240, 130, 40, 0.92)',    // orange
  ];
  // Parse a palette string into [r,g,b,a]. Accepts rgb(...) and rgba(...).
  const _parseCol = (s)=>{
    const m=String(s).match(/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)(?:[,\s]+([\d.]+))?\)/);
    if(!m) return [128,128,128,1];
    return [+m[1], +m[2], +m[3], m[4]!=null?+m[4]:1];
  };
  // Pick a palette colour AND set per-element chord energy so Real tone
  // modulates each line/triangle/ring with the corresponding chord's dynamic.
  // i = element index (maps onto the chords array uniformly).
  const _cn = chords && chords.length ? chords.length : 1;
  const pickPalette = (i)=>{
    if(chords && chords.length){
      const ch = chords[i % _cn];
      _setCurE(ch && ch._E);
    }
    const colStr = lineColors[i % lineColors.length];
    const [pr,pg,pb,pa] = _parseCol(colStr);
    let r=pr,g=pg,b=pb;
    if(typeof _energyTint === 'function'){ const t=_energyTint(r,g,b); r=t[0]; g=t[1]; b=t[2]; }
    if(typeof _pastelTint === 'function'){ const p=_pastelTint(r,g,b); r=p[0]; g=p[1]; b=p[2]; }
    return `rgba(${r|0},${g|0},${b|0},${pa})`;
  };

  // === 1. LARGE OUTLINED TRIANGLES ===
  const triCount = countFor(TH_TRI);
  for(let i=0; i<triCount; i++){
    const rnd = _seedRnd(1000+i, ss, 0, 0);
    const sizeScale = 0.28 + rnd()*0.45;
    const baseSize = Math.min(CW, CH) * sizeScale;
    const cx = rnd()*CW;
    const cy = rnd()*CH;
    const rot = rnd()*Math.PI*2;
    const elongate = 0.6 + rnd()*0.8;
    const v = [];
    for(let k=0; k<3; k++){
      const a = rot + k*(Math.PI*2/3) + (rnd()-0.5)*0.4;
      v.push({ x: cx + Math.cos(a)*baseSize*elongate, y: cy + Math.sin(a)*baseSize });
    }
    ctx.strokeStyle = pickPalette(i);
    ctx.lineWidth = Math.max(1.5, Math.min(CW,CH)*(0.004 + rnd()*0.004));
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(v[0].x, v[0].y);
    ctx.lineTo(v[1].x, v[1].y);
    ctx.lineTo(v[2].x, v[2].y);
    ctx.closePath();
    ctx.stroke();
  }

  // === 2. LARGE CONCENTRIC CIRCLE RINGS (no fill) ===
  const ringCount = countFor(TH_RING);
  for(let i=0; i<ringCount; i++){
    const rnd = _seedRnd(2000+i, ss, 0, 0);
    const cx = CW*0.10 + rnd()*CW*0.80;
    const cy = CH*0.10 + rnd()*CH*0.80;
    const outerR = Math.min(CW, CH) * (0.10 + rnd()*0.12);
    const nestedRings = 2 + Math.floor(rnd()*3); // 2-4 nested
    // Pick 2 colors and alternate
    const c1 = pickPalette(i);
    const c2 = pickPalette(i);
    for(let k=0; k<nestedRings; k++){
      const ringR = outerR * (1 - k * 0.65/nestedRings);
      ctx.strokeStyle = k % 2 === 0 ? c1 : c2;
      ctx.lineWidth = Math.max(1.5, Math.min(CW,CH)*(0.003 + rnd()*0.003));
      ctx.beginPath();
      ctx.arc(cx, cy, ringR, 0, Math.PI*2);
      ctx.stroke();
    }
  }

  // === 3. LONG DIAGONAL LINES ===
  const lineCount = countFor(TH_LINE);
  ctx.lineCap = 'round';
  for(let i=0; i<lineCount; i++){
    const rnd = _seedRnd(3000+i, ss, 0, 0);
    const angle = rnd() * Math.PI;
    const cx = rnd()*CW;
    const cy = rnd()*CH;
    const length = Math.max(CW, CH) * (0.5 + rnd()*0.7);
    ctx.strokeStyle = pickPalette(i);
    ctx.lineWidth = Math.max(1, Math.min(CW,CH)*(0.0025 + rnd()*0.003));
    ctx.beginPath();
    ctx.moveTo(cx - Math.cos(angle)*length/2, cy - Math.sin(angle)*length/2);
    ctx.lineTo(cx + Math.cos(angle)*length/2, cy + Math.sin(angle)*length/2);
    ctx.stroke();
  }

  // === 4. ARC / CRESCENT FRAGMENTS ===
  const arcCount = countFor(TH_ARC);
  ctx.lineCap = 'round';
  for(let i=0; i<arcCount; i++){
    const rnd = _seedRnd(4000+i, ss, 0, 0);
    const cx = CW*0.15 + rnd()*CW*0.70;
    const cy = CH*0.15 + rnd()*CH*0.70;
    const arcR = Math.min(CW, CH) * (0.12 + rnd()*0.15);
    const startA = rnd() * Math.PI * 2;
    const sweep = (0.4 + rnd()*0.8) * Math.PI;
    ctx.strokeStyle = pickPalette(i);
    ctx.lineWidth = Math.max(2, Math.min(CW,CH)*(0.005 + rnd()*0.005));
    ctx.beginPath();
    ctx.arc(cx, cy, arcR, startA, startA + sweep);
    ctx.stroke();
  }

  // === 5. BIG ZIGZAG LIGHTNING ===
  const zigCount = countFor(TH_ZIG);
  for(let i=0; i<zigCount; i++){
    const rnd = _seedRnd(5000+i, ss, 0, 0);
    const segCount = 4 + Math.floor(rnd()*4);
    const segLen = Math.min(CW, CH) * (0.08 + rnd()*0.06);
    const baseAng = rnd() * Math.PI * 2;
    const cosA = Math.cos(baseAng), sinA = Math.sin(baseAng);
    const perpX = -sinA, perpY = cosA;
    const amp = segLen * 0.9;
    let zx = rnd()*CW;
    let zy = rnd()*CH;
    ctx.strokeStyle = pickPalette(i);
    ctx.lineWidth = Math.max(1.8, Math.min(CW,CH)*(0.004 + rnd()*0.003));
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(zx, zy);
    for(let k=0; k<segCount; k++){
      const dir = k % 2 === 0 ? 1 : -1;
      zx += cosA * segLen + perpX * amp * dir;
      zy += sinA * segLen + perpY * amp * dir;
      ctx.lineTo(zx, zy);
    }
    ctx.stroke();
  }
}

// ── Kandinsky Bauhaus engine ─────────────────────────────────────────────────
// The vocabulary of the Bauhaus years, each form a primitive: the circle with
// its coloured halo, the bundle of straight lines, the acute triangle, the
// checkerboard patch, the arc, the free lobed form. A composition is a list of
// forms with musical time; drawn up to the reveal, so the picture assembles
// as the piece plays and repaints identically for the same song and seed.
const _kdR=(a,ss)=>_seedRnd(a,ss,0,0);
const _kdClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const _kdMix=(a,b,t)=>[a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t];
const _kdCss=(c,a)=>`rgba(${c[0]|0},${c[1]|0},${c[2]|0},${a==null?1:a})`;
const _KD_Y=[236,196,36], _KD_R=[204,52,42], _KD_B=[38,74,160], _KD_K=[26,24,28], _KD_W=[244,240,230];
// a chord colour pushed to Kandinsky's flat poster chroma
