      let root=bp; if(b===3) root=dPc(4); else { const cand=[bp, inScale((bp+8)%12), inScale((bp+9)%12)]; for(const c of cand){ const tri=_fmTri(kit,scAbs,c); if(tri.indexOf(bp)>=0){ root=c; break; } } }
