  chords[NB*2-1]=chords[NB*2-2]={pcs:(chordOf(hn-1)||prev).pcs.indexOf(tonic)>=0 ? (chordOf(hn-1)||prev).pcs : [tonic,(tonic+4)%12,(tonic+7)%12], root:tonic};   // it closes at home
