  let h=mx===R?((G-B)/d)%6:mx===G?(B-R)/d+2:(R-G)/d+4; h*=60; if(h<0) h+=360; let k=0,bd=1e9; for(let i=0;i<12;i++){ const dd=Math.min(Math.abs(h-_BH_ITTEN_H[i]),360-Math.abs(h-_BH_ITTEN_H[i])); if(dd<bd){ bd=dd; k=i; } }
