  const cols=Math.max(3,Math.min(6,Math.round((3+(A.ch?A.ch.density:0.3)*4)*_dW((A.ch?A.ch.density:0.3))))); const cw=CW/cols, rows=Math.max(3,Math.round(CH/cw)), chh=CH/rows, tot=cols*rows;
