  if(trend>0.55){ push(0.05,()=>{ ctx.save(); ctx.translate(CW/2,CH/2); ctx.rotate(-0.78); ctx.fillStyle=_bhCss(INK); ctx.fillRect(-D*0.7,-D*0.006,D*1.4,D*0.012); ctx.restore(); }); }
